<?php
declare(strict_types=1);
require __DIR__.'/support/Harness.php';
require __DIR__.'/support/HttpClient.php';
ob_start();
$environment=new TestEnvironment();
$server=new TestHttpServer($environment);
$suite=new Suite();
$customerPages=['/account','/account?section=bookings','/account?section=passengers','/account?section=tickets','/account?section=profile','/flights','/flights/details?id=1','/booking/passengers','/booking/confirmation?id=1','/seat-selection','/payments'];
$adminPages=['/admin','/admin/airlines','/admin/airports','/admin/flights','/admin/seats','/admin/bookings','/admin/payments','/admin/payment-proof?id=1'];
$customerPosts=['/bookings/cancel','/flights/select','/booking/review','/booking/create','/seat-selection/save','/payments/submit'];
$redirect=static function(array $response,string $location):void{equal($response['status'],303);equal($response['headers']['location']??null,$location);};
$client=fn()=>new TestClient($server->url);
foreach(array_merge($customerPages,$adminPages,['/flights?seat_counts=1&ids=1','/admin?dashboard_data=1']) as $path)$suite->add('security: guest blocked '.$path,function()use($client,$path,$redirect){$redirect($client()->request($path),'/login');});
foreach(array_merge($customerPosts,['/admin/action','/admin/logout']) as $path)$suite->add('security: guest cannot POST '.$path,function()use($client,$path,$redirect){$redirect($client()->request($path,[],'POST'),'/login');});
foreach($adminPages as $path)$suite->add('security: customer cannot access '.$path,function()use($client,$path){$c=$client();$c->login();equal($c->request($path)['status'],403);});
foreach($customerPages as $path)$suite->add('security: admin cannot access '.$path,function()use($client,$path){$c=$client();$c->login('admin@example.test');equal($c->request($path)['status'],403);});
foreach(array_merge($customerPosts,['/logout']) as $path)$suite->add('security: CSRF rejects missing, array and forged token '.$path,function()use($client,$path){$c=$client();$c->login();foreach([[],['_csrf'=>[]],['_csrf'=>str_repeat('0',64)]] as $data)equal($c->request($path,$data,'POST')['status'],419);});
foreach(['/admin/action','/admin/logout'] as $path)$suite->add('security: admin CSRF '.$path,function()use($client,$path){$c=$client();$c->login('admin@example.test');equal($c->request($path,[],'POST')['status'],419);});
foreach(['/login','/register','/admin/login'] as $path)$suite->add('security: public forms require CSRF '.$path,function()use($client,$path){equal($client()->request($path,[],'POST')['status'],419);});
$suite->add('functional: home is public for guests, customers and admins; headers and cookies are secure',function()use($client){foreach([null,'one@example.test','admin@example.test'] as $email){$c=$client();if($email)$c->login($email);$r=$c->request('/');equal($r['status'],200);equal($r['headers']['x-content-type-options'],'nosniff');equal($r['headers']['x-frame-options'],'DENY');} $r=$client()->request('/login');$cookie=strtolower($r['headers']['set-cookie']);expect(str_contains($cookie,'httponly'));expect(str_contains($cookie,'samesite=lax'));});
foreach(array_slice($adminPages,0,-1) as $path)$suite->add('functional: admin renders '.$path,function()use($client,$path){$c=$client();$c->login('admin@example.test');equal($c->request($path)['status'],200);});
foreach(['/account','/account?section=bookings','/account?section=passengers','/account?section=tickets','/account?section=profile','/flights','/flights/details?id=1','/seat-selection','/payments'] as $path)$suite->add('functional: customer renders '.$path,function()use($client,$path){$c=$client();$c->login();equal($c->request($path)['status'],200);});
$suite->add('security: login rotates cookie and token; logout invalidates both session and old token',function()use($client,$redirect){$c=$client();$oldToken=$c->token();$oldCookies=$c->cookies;$c->login();expect($oldCookies!==$c->cookies);equal($c->request('/logout',['_csrf'=>$oldToken],'POST')['status'],419);$token=$c->token('/account');$redirect($c->request('/logout',['_csrf'=>$token],'POST'),'/login');$redirect($c->request('/account'),'/login');$replay=$client();$replay->cookies=$oldCookies;$redirect($replay->request('/account'),'/login');});
$suite->add('security: suspended account loses access on next request',function()use($client,$environment,$redirect){$c=$client();$c->login();$environment->db->exec("UPDATE users SET status='suspended' WHERE id=1");$redirect($c->request('/account'),'/login');});
$suite->add('functional/security: registration cannot grant admin role and escapes displayed names',function()use($client,$environment,$redirect){$c=$client();$redirect($c->request('/register',['_csrf'=>$c->token('/register'),'full_name'=>'<script>alert(1)</script>','email'=>'NEW@example.test','password'=>'Password123!','password_confirmation'=>'Password123!','role'=>'admin'],'POST'),'/account');equal($environment->scalar("SELECT role FROM users WHERE email='new@example.test'"),'customer');$body=$c->request('/account')['body'];expect(!str_contains($body,'<script>alert(1)</script>'));expect(str_contains($body,'&lt;script&gt;'));});
foreach([['email'=>"' OR 1=1 --"],['password'=>'wrong'],['email'=>'suspended@example.test'],['email'=>['one@example.test']]] as $index=>$invalid)$suite->add('security: invalid login '.$index,function()use($client,$redirect,$invalid){$c=$client();$data=array_replace(['_csrf'=>$c->token(),'email'=>'one@example.test','password'=>'Password123!'],$invalid);$redirect($c->request('/login',$data,'POST'),'/login');$redirect($c->request('/account'),'/login');});
$suite->add('functional: booking, seats, payment, admin verification, tickets and cancellation over HTTP',function()use($client,$environment,$redirect){
    $c=$client();$c->login();$token=$c->token('/flights');$redirect($c->request('/flights/select',['_csrf'=>$token,'flight_id'=>1],'POST'),'/booking/passengers');
    equal($c->request('/booking/passengers')['status'],200);
    $r=$c->request('/booking/review',['_csrf'=>$token,'passengers'=>[$environment->passenger('First'),$environment->passenger('Second')]],'POST');equal($r['status'],200);
    $r=$c->request('/booking/create',['_csrf'=>$token],'POST');equal($r['status'],303);$id=(int)$environment->scalar('SELECT id FROM bookings');equal($r['headers']['location'],'/booking/confirmation?id='.$id);equal($c->request($r['headers']['location'])['status'],200);
    $ids=$environment->db->query('SELECT id FROM passengers ORDER BY id')->fetchAll(PDO::FETCH_COLUMN);$selection=array_combine($ids,[1,2]);
    equal($c->request('/seat-selection?booking_id='.$id)['status'],200);$redirect($c->request('/seat-selection/save',['_csrf'=>$token,'booking_id'=>$id,'passengers'=>$selection],'POST'),'/payments?booking_id='.$id);
    $availability=json_decode($c->request('/flights?seat_counts=1&ids=1')['body'],true,512,JSON_THROW_ON_ERROR);equal($availability['flights'][0]['available_seats'],4);
    $booking=['id'=>$id,'total_amount'=>'20.50'];$redirect($c->request('/payments/submit',$environment->payment($booking)+['_csrf'=>$token,'booking_id'=>$id],'POST'),'/payments?booking_id='.$id);
    $payment=(int)$environment->scalar('SELECT id FROM payments');$a=$client();$a->login('admin@example.test');$redirect($a->request('/admin/action',['_csrf'=>$a->token('/admin'),'kind'=>'payment','id'=>$payment,'decision'=>'verified','return_to'=>'/admin/payments'],'POST'),'/admin/payments');
    equal((int)$environment->scalar('SELECT COUNT(*) FROM e_tickets'),2);equal($environment->scalar('SELECT status FROM bookings'),'confirmed');equal($c->request('/account?section=tickets')['status'],200);
    equal($c->request('/bookings/cancel',['_csrf'=>$token,'booking_id'=>$id],'POST')['status'],303);equal($environment->scalar('SELECT status FROM bookings'),'cancelled');equal((int)$environment->scalar('SELECT COUNT(*) FROM booking_seats'),0);
});
$suite->add('security: cross-customer HTTP access cannot read or mutate bookings',function()use($client,$environment,$redirect){$b=$environment->booking();$selection=$environment->assign($b);$c=$client();$c->login('two@example.test');$token=$c->token('/account');foreach(['/booking/confirmation?id='.$b['id'],'/seat-selection?booking_id='.$b['id'],'/payments?booking_id='.$b['id']] as $path){$r=$c->request($path);equal($r['status'],303);expect(!str_contains($r['body'],$b['pnr']));}foreach([['/bookings/cancel',['booking_id'=>$b['id']]],['/seat-selection/save',['booking_id'=>$b['id'],'passengers'=>$selection]],['/payments/submit',$environment->payment($b)+['booking_id'=>$b['id']]]] as [$path,$data])equal($c->request($path,$data+['_csrf'=>$token],'POST')['status'],303);equal($environment->scalar('SELECT status FROM bookings'),'pending');equal((int)$environment->scalar('SELECT COUNT(*) FROM payments'),0);equal((int)$environment->scalar('SELECT COUNT(*) FROM booking_seats'),1);});
foreach(['0','1%20OR%201=1','1,,2','-1','1&ids[]=2'] as $ids)$suite->add('security: reject malformed JSON IDs '.$ids,function()use($client,$ids){$c=$client();$c->login();equal($c->request('/flights?seat_counts=1&ids='.$ids)['status'],400);});
$suite->add('functional: live chart JSON returns unique booking and payment totals',function()use($client,$environment){$b=$environment->booking(1,2);$environment->assign($b,1,[1,2]);(new App\Models\AdminModel($environment->db))->reviewPayment($environment->submitted($b),'verified');$c=$client();$c->login('admin@example.test');$r=$c->request('/admin?dashboard_data=1');equal($r['status'],200);equal($r['headers']['cache-control'],'no-store');$data=json_decode($r['body'],true,512,JSON_THROW_ON_ERROR);equal(array_sum($data['bookingStatuses']['values']),1);equal(array_sum($data['paymentStatuses']['values']),1);equal(array_sum($data['revenue']['values']),20.5);});
$suite->add('functional/security: admin CRUD, seat generation and unsafe redirect rejection',function()use($client,$environment,$redirect){$c=$client();$c->login('admin@example.test');$token=$c->token('/admin');$redirect($c->request('/admin/action',['_csrf'=>$token,'kind'=>'airlines','name'=>'New Airline','iata_code'=>'XY','icao_code'=>'XYZ','status'=>'active','return_to'=>'https://evil.test'],'POST'),'/admin');equal((int)$environment->scalar('SELECT COUNT(*) FROM airlines'),2);$r=$c->request('/admin/action',['_csrf'=>$token,'kind'=>'seats','flight_id'=>1,'rows'=>1,'letters'=>range('A','K'),'cabin_class'=>'business'],'POST');equal($r['status'],303);equal((int)$environment->scalar('SELECT COUNT(*) FROM seats WHERE flight_id=1'),15);});
$suite->add('security: payment proof traversal cannot disclose configuration',function()use($client,$environment){$b=$environment->booking();$environment->assign($b);$id=$environment->submitted($b);$environment->db->prepare('UPDATE payments SET proof_path=? WHERE id=?')->execute(['../../.env',$id]);$c=$client();$c->login('admin@example.test');equal($c->request('/admin/payment-proof?id='.$id)['status'],404);});
$suite->add('functional: missing routes and wrong HTTP methods return 404 and 405',function()use($client){$c=$client();equal($c->request('/does-not-exist')['status'],404);equal($c->request('/flights/select')['status'],405);equal($c->request('/login',[],'PUT')['status'],405);});
foreach([['first_name'=>''],['last_name'=>['invalid']],['date_of_birth'=>'2026-02-30'],['date_of_birth'=>'2099-01-01'],['gender'=>'invalid'],['passport_number'=>'ABC','passport_country'=>''],['passport_number'=>str_repeat('X',31),'passport_country'=>'PK'],['passport_country'=>'PAK']] as $index=>$invalid)$suite->add('functional: passenger validation rejects invalid fields '.$index,function()use($client,$environment,$invalid,$redirect){$c=$client();$c->login();$token=$c->token('/flights');$c->request('/flights/select',['_csrf'=>$token,'flight_id'=>1],'POST');$redirect($c->request('/booking/review',['_csrf'=>$token,'passengers'=>[array_replace($environment->passenger(),$invalid)]],'POST'),'/booking/passengers');equal((int)$environment->scalar('SELECT COUNT(*) FROM bookings'),0);});
foreach([[],array_fill(0,10,[]),'invalid'] as $index=>$passengers)$suite->add('functional: invalid passenger count/type '.$index,function()use($client,$passengers,$redirect){$c=$client();$c->login();$token=$c->token('/flights');$c->request('/flights/select',['_csrf'=>$token,'flight_id'=>1],'POST');$redirect($c->request('/booking/review',['_csrf'=>$token,'passengers'=>$passengers],'POST'),'/booking/passengers');});
foreach([['full_name'=>[]],['email'=>'invalid'],['email'=>'one@example.test'],['password'=>'short'],['password_confirmation'=>'mismatch'],['password'=>str_repeat('X',73),'password_confirmation'=>str_repeat('X',73)]] as $index=>$invalid)$suite->add('functional: registration validation rejects invalid fields '.$index,function()use($client,$environment,$invalid,$redirect){$c=$client();$redirect($c->request('/register',array_replace(['_csrf'=>$c->token('/register'),'full_name'=>'New User','email'=>'new@example.test','password'=>'Password123!','password_confirmation'=>'Password123!'],$invalid),'POST'),'/register');equal((int)$environment->scalar('SELECT COUNT(*) FROM users'),4);$redirect($c->request('/account'),'/login');});
$suite->add('regression: sold-out selection shows alert and cannot start booking',function()use($client,$environment,$redirect){$c=$client();$c->login();$token=$c->token('/flights');$environment->db->exec("UPDATE seats SET status='blocked' WHERE flight_id=1");$redirect($c->request('/flights/select',['_csrf'=>$token,'flight_id'=>1],'POST'),'/flights');expect(str_contains($c->request('/flights')['body'],'No seats available'));$redirect($c->request('/booking/passengers'),'/flights');equal((int)$environment->scalar('SELECT COUNT(*) FROM bookings'),0);});
$suite->add('regression: booking creation without review or repeated create never duplicates booking',function()use($client,$environment,$redirect){$c=$client();$c->login();$token=$c->token('/flights');$redirect($c->request('/booking/create',['_csrf'=>$token],'POST'),'/booking/passengers');$c->request('/flights/select',['_csrf'=>$token,'flight_id'=>1],'POST');equal($c->request('/booking/review',['_csrf'=>$token,'passengers'=>[$environment->passenger()]],'POST')['status'],200);equal($c->request('/booking/create',['_csrf'=>$token],'POST')['status'],303);$redirect($c->request('/booking/create',['_csrf'=>$token],'POST'),'/booking/passengers');equal((int)$environment->scalar('SELECT COUNT(*) FROM bookings'),1);});
$suite->add('functional: admin rejection creates no tickets and allows customer resubmission',function()use($client,$environment){$b=$environment->booking();$environment->assign($b);$id=$environment->submitted($b);$a=$client();$a->login('admin@example.test');equal($a->request('/admin/action',['_csrf'=>$a->token('/admin'),'kind'=>'payment','id'=>$id,'decision'=>'rejected'],'POST')['status'],303);equal($environment->scalar('SELECT status FROM payments'),'rejected');equal($environment->scalar('SELECT status FROM bookings'),'pending');equal((int)$environment->scalar('SELECT COUNT(*) FROM e_tickets'),0);$c=$client();$c->login();equal($c->request('/payments/submit',$environment->payment($b,'RETRY-001')+['_csrf'=>$c->token('/account'),'booking_id'=>$b['id']],'POST')['status'],303);equal((int)$environment->scalar('SELECT COUNT(*) FROM payments'),2);});
try{$failures=$suite->run(fn()=> $environment->reset());}finally{$server->stop();session_write_close();$environment->cleanup();}
echo ob_get_clean();exit($failures?1:0);
